import{_ as t,o,c as n,a2 as a}from"./chunks/framework.vLhlLNVn.js";const f=JSON.parse('{"title":"Which settings does the adapter have and what do they do?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/03.referenz/01.einstellungen.md"},"headers":[],"relativePath":"adapter/esphome/referenz/einstellungen.md","filePath":"adapter/esphome/referenz/einstellungen.md","lastUpdated":1795571670000}'),i={name:"adapter/esphome/referenz/einstellungen.md"};function d(s,e,r,c,h,l){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="which-settings-does-the-adapter-have-and-what-do-they-do" tabindex="-1">Which settings does the adapter have and what do they do? <a class="header-anchor" href="#which-settings-does-the-adapter-have-and-what-do-they-do" aria-label="Permalink to &quot;Which settings does the adapter have and what do they do?&quot;">​</a></h1><p><a id="reconnect-settings-exist-happens-device"></a></p><h2 id="which-reconnect-settings-exist-and-what-happens-when-a-device-goes-offline" tabindex="-1">Which reconnect settings exist and what happens when a device goes offline? <a class="header-anchor" href="#which-reconnect-settings-exist-and-what-happens-when-a-device-goes-offline" aria-label="Permalink to &quot;Which reconnect settings exist and what happens when a device goes offline?&quot;">​</a></h2><p>After every connection loss the adapter reconnects by itself, until the device answers again. How quickly it notices an outage and how often it retries is set in the &quot;Main settings&quot; tab under &quot;Connection behavior for known devices&quot;. The values apply to all devices of the instance.</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th><th>Default</th><th>Allowed</th></tr></thead><tbody><tr><td>&quot;Reconnect interval (seconds)&quot;</td><td>wait time before every new connection attempt</td><td>30</td><td>1 to 3600</td></tr><tr><td>&quot;Ping interval (seconds)&quot;</td><td>how often the adapter pings a connected device</td><td>5</td><td>1 to 3600</td></tr><tr><td>&quot;Ping attempts before offline&quot;</td><td>how many pings in a row may fail before the device counts as offline</td><td>1</td><td>1 to 100</td></tr></tbody></table><p>The help text under &quot;Reconnect interval&quot; says 5 seconds. The adapter only uses this value when the field is empty. What is in the field applies.</p><p>With a 5-second ping interval and 1 ping attempt, the adapter notices an outage after about 5 seconds. With 3 attempts it takes about 15 seconds, but a single lost ping on Wi-Fi does not drop the connection.</p><h3 id="what-happens-when-a-device-goes-offline" tabindex="-1">What happens when a device goes offline <a class="header-anchor" href="#what-happens-when-a-device-goes-offline" aria-label="Permalink to &quot;What happens when a device goes offline&quot;">​</a></h3><ol><li>The adapter notices the drop, because the connection breaks or the configured pings fail.</li><li><code>esphome.0.&lt;device&gt;.info._online</code> becomes <code>false</code>, <code>info._connectionStatus</code> names the reason.</li><li>After the &quot;Reconnect interval&quot; the adapter connects again, without limit.</li><li>When the device answers again, it reads device information and entities again. The log shows &quot;ESPHome client &lt;IP&gt; connected&quot;.</li></ol><p>You do not need to restart the adapter for this.</p><h3 id="the-status-display" tabindex="-1">The status display <a class="header-anchor" href="#the-status-display" aria-label="Permalink to &quot;The status display&quot;">​</a></h3><p><code>info._online</code> is <code>true</code> while the device is connected and has the role <code>indicator.reachable</code>. The &quot;Devices&quot; tab shows the same status. <code>esphome.0.info.connectedDevices</code> lists the names of all connected devices, <code>esphome.0.info.connection</code> is <code>true</code> while the instance runs.</p><p><code>info._connectionStatus</code> names the state as text:</p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>connecting</code>, <code>initializing</code>, <code>Initializing</code></td><td>Connecting or reading the device.</td></tr><tr><td><code>Connected</code>, <code>connected</code>, <code>initialized</code></td><td>Connected, values are arriving.</td></tr><tr><td><code>disconnected</code></td><td>Disconnected, the next attempt follows after the &quot;Reconnect interval&quot;.</td></tr><tr><td><code>connection lost</code></td><td>Connection broke (<code>ECONNRESET</code>).</td></tr><tr><td><code>unreachable</code></td><td>The device does not answer.</td></tr><tr><td><code>No Network</code></td><td>The network of the ioBroker host is not ready yet.</td></tr><tr><td><code>API password incorrect</code></td><td>The API password is wrong.</td></tr><tr><td><code>Encryption Key Missing</code></td><td>The device requires an encryption key, the adapter has none.</td></tr><tr><td><code>error</code></td><td>Another error, the message is in the log.</td></tr></tbody></table><p>Waiting does not help with <code>API password incorrect</code> and <code>Encryption Key Missing</code>. Enter the correct credentials in the &quot;Devices&quot; tab under &quot;Change connection settings&quot;.</p><h3 id="when-a-device-stays-offline" tabindex="-1">When a device stays offline <a class="header-anchor" href="#when-a-device-stays-offline" aria-label="Permalink to &quot;When a device stays offline&quot;">​</a></h3><ol><li>Read what the log reports for the device. The meaning is under <a href="./log-meldungen#log-full-errors-connections-drop">Log messages</a>.</li><li>Check that the device can be reached on the network, e.g. through its web page if it uses <code>web_server:</code>.</li><li>Restart the device. If it does not come back by itself, restart the instance.</li></ol><p><strong>See also:</strong> <a href="./datenpunkte#online-status-wifi-signal-ip">Online status, Wi-Fi signal and IP of a device</a> · <a href="./../fehlerbehebung/verbindung#devices-offline-reporting-incorrect-password">Devices offline or reporting &quot;incorrect password&quot;</a> · <a href="./../hintergrund/adapter-und-dashboard#adapter-dashboard-show-device-status">Why adapter and dashboard show the status differently</a></p><p><a id="show-configuration-states-info-config"></a></p><h2 id="what-does-the-option-show-configuration-states-do-and-what-are-the-info-and-config-folders" tabindex="-1">What does the option &quot;Show configuration states&quot; do, and what are the info and config folders? <a class="header-anchor" href="#what-does-the-option-show-configuration-states-do-and-what-are-the-info-and-config-folders" aria-label="Permalink to &quot;What does the option &quot;Show configuration states&quot; do, and what are the info and config folders?&quot;">​</a></h2><p>Every device has two folders with additional information.</p><p>The adapter always creates <strong><code>info</code></strong> once the device is connected. It holds what the device reports about itself, e.g. name, MAC address, ESPHome version, compile time and model, plus <code>_online</code> and <code>_connectionStatus</code>.</p><p><strong><code>config</code></strong> exists under every entity when &quot;Show configuration states&quot; is on. The option is in the tab &quot;Main settings&quot; and is off by default. The folder shows the configuration of the entity from the API, e.g. name, unit, device class and decimals. The values are read-only, nested data is stored as JSON text in one state.</p><p>If the option is off, the adapter deletes existing <code>config</code> folders on the next connection. You do not need them for control. The only exception is <code>config.rgbAutoWhite</code> of RGBW lights.</p><p><strong>See also:</strong> <a href="./../anleitungen/automatisieren#use-white-channel-rgbw-lamp">Use the white channel automatically</a> · <a href="./datenpunkte#online-status-wifi-signal-ip">Online status of a device</a></p>',25)])])}const u=t(i,[["render",d]]);export{f as __pageData,u as default};
